/* === Module: js/mobile/keyboardInteractionManager.js === */
/**
 * keyboardInteractionManager.js — Centralized Virtual Keyboard Handler
 * Mobile Phase M1.1 (UMFIS)
 *
 * Smoothly repositions active focused fields, prevents keyboard overlap,
 * avoids content displacement/jumping, and preserves draft input text.
 */

'use strict';

(function(exports) {

  class KeyboardInteractionManager {
    constructor() {
      this.isKeyboardOpen = false;
      this.activeField = null;
    }

    init() {
      if (typeof window === 'undefined' || !window.document) return;
      this.setupFocusListeners();
      this.setupViewportListeners();
    }

    setupFocusListeners() {
      document.addEventListener('focusin', (e) => {
        if (this.isInputElement(e.target)) {
          this.activeField = e.target;
          this.isKeyboardOpen = true;
          this.ensureVisible(e.target);
        }
      });

      document.addEventListener('focusout', (e) => {
        if (e.target === this.activeField) {
          this.activeField = null;
          this.isKeyboardOpen = false;
        }
      });
    }

    setupViewportListeners() {
      if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', () => {
          if (this.activeField && this.isKeyboardOpen) {
            this.ensureVisible(this.activeField);
          }
        });
      }
    }

    ensureVisible(element) {
      if (!element) return;
      setTimeout(() => {
        try {
          element.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
        } catch (e) {
          element.scrollIntoView(false);
        }
      }, 100);
    }

    isInputElement(el) {
      if (!el) return false;
      const tag = el.tagName ? el.tagName.toUpperCase() : '';
      return tag === 'INPUT' || tag === 'TEXTAREA' || el.isContentEditable;
    }
  }

  const instance = new KeyboardInteractionManager();
  if (typeof window !== 'undefined') window.KeyboardInteractionManager = instance;
  exports.KeyboardInteractionManager = instance;

})(typeof exports !== 'undefined' ? exports : window);

;

/* === Module: js/mobile/keyboardViewport.js === */
/**
 * keyboardViewport.js — Keyboard Viewport Resizing Engine
 * Mobile Phase M1.2 (MSAVS)
 *
 * When the virtual keyboard opens, shrinks ONLY Layer 3 (Primary Content Layer).
 * Keeps Layer 2 (Header) and Layer 4 (Persistent Bottom Area) locked without layout jumping.
 */

'use strict';

(function(exports) {

  class KeyboardViewport {
    constructor() {
      this.keyboardOpen = false;
      this.keyboardHeight = 0;
    }

    init() {
      if (typeof window === 'undefined' || !window.document) return;
      this.bindViewportListeners();
    }

    bindViewportListeners() {
      if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', () => {
          const windowHeight = window.innerHeight;
          const visualHeight = window.visualViewport.height;
          const diff = windowHeight - visualHeight;

          if (diff > 150) {
            // Keyboard is open
            this.keyboardOpen = true;
            this.keyboardHeight = diff;
            this.applyKeyboardLayout(true, diff);
          } else {
            // Keyboard is closed
            this.keyboardOpen = false;
            this.keyboardHeight = 0;
            this.applyKeyboardLayout(false, 0);
          }
        });
      }
    }

    applyKeyboardLayout(isOpen, kbHeight) {
      if (typeof document === 'undefined') return;
      const root = document.documentElement;
      const contentLayer = document.querySelector('.m-layer-content');

      if (isOpen) {
        root.classList.add('m-keyboard-open');
        root.style.setProperty('--m-keyboard-height', `${kbHeight}px`);
        if (contentLayer) {
          contentLayer.style.maxHeight = `calc(100vh - ${kbHeight}px - 56px)`;
        }
      } else {
        root.classList.remove('m-keyboard-open');
        root.style.setProperty('--m-keyboard-height', '0px');
        if (contentLayer) {
          contentLayer.style.maxHeight = '';
        }
      }
    }
  }

  const instance = new KeyboardViewport();
  if (typeof window !== 'undefined') window.KeyboardViewport = instance;
  exports.KeyboardViewport = instance;

})(typeof exports !== 'undefined' ? exports : window);

;

